package com.oms.order.service;

import com.oms.common.api.OrderStockClient;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.util.*;
import java.util.function.Function;
import com.fasterxml.jackson.databind.JsonNode;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.*;

/** Continue the same approved exchange with a new replacement demand, never another return or SO. */
@Service public class ExchangeContinuationService {
    @Resource private OrderRepository repository;
    @Resource private ExchangeService exchanges;
    @Resource private ExchangeReturnClient returns;
    @Resource private OrderShipmentWmsClient wms;
    @Resource private OrderStockClient stock;
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    private void idle(Map<String,Object> e){require(e.get("lease_until")==null||!time(text(e,"lease_until")).isAfter(LocalDateTime.now()),"换货任务正在执行，请稍后刷新");}
    private Map<String,Object> base(String company,long id){Map<String,Object> e=exchanges.row(company,id,false);require(!ExchangeFulfillment.unshipped(e)&&e.get("linked_exchange_id")==null,"请在实际退回换出的处理单继续换出");require(e.get("approved_snapshot")!=null&&"PASSED".equals(text(e,"return_qc")),"请先完成原退回验收");require("NONE".equals(text(e,"platform_operation")),"原平台操作尚未核对");require(!text(e,"problem_codes").contains("SOURCE_CONFLICT")&&!text(e,"problem_codes").contains("APPLICATION_CHANGED")&&!text(e,"problem_codes").contains("LINKED_PLATFORM_REVIEW"),"来源或平台申请已变化，请先核对");return e;}
    private void stopped(Map<String,Object> e){require("CLOSED".equals(text(e,"state"))||number(e,"fulfillment_hold")==1&&Arrays.asList("HOLD","CONTINUE_REVIEW").contains(text(e,"control_state")),"仅已结束或已终止剩余换出的挂起单可申请；普通撤回请恢复履约");}
    private long shipped(String company,long id){return repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE'",Long.class,company,id);}
    private long active(String company,long id){return repository.db().queryForObject("SELECT COALESCE(SUM(quantity-cancelled_quantity),0) FROM oms_order_line WHERE company_code=? AND exchange_id=? AND business_type='EXCHANGE'",Long.class,company,id)-shipped(company,id);}
    private Map<String,Object> returned(String company,Map<String,Object> e){Map<String,Object> result=data(returns.detail(company,number(e,"id"),SecurityConstants.INNER));require(number(result,"pending_review_count")==0,"存在待人工核对的退回回传");require(number(result,"posted_quantity")==number(e,"requested_quantity")&&number(result,"accepted_quantity")==number(e,"requested_quantity")&&"COMPLETED".equals(text(result,"receipt_state")),"原退回数量尚未完整入账，不能复用验收继续换出");return result;}
    private void receipts(String company,long id){
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_outbound o JOIN oms_order_shipment s ON s.company_code=o.company_code AND s.id=o.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE' AND o.state<>'COMPLETED'",Long.class,company,id)==0,"换出回执尚未完成记账");
        require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_virtual_outbound o JOIN oms_order_shipment s ON s.company_code=o.company_code AND s.id=o.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE' AND o.state<>'COMPLETED'",Long.class,company,id)==0,"虚拟出库结果尚未确认");
        List<Map<String,Object>> ships=repository.db().query("SELECT id,shipment_sn FROM oms_order_shipment WHERE company_code=? AND exchange_id=? AND business_type='EXCHANGE' ORDER BY id LIMIT 101",ROW,company,id);require(ships.size()<=100,"发货单较多，请先核对本次执行范围");
        if(!ships.isEmpty()){List<Long> ids=new ArrayList<>();for(Map<String,Object> s:ships)ids.add(number(s,"id"));List<Map<String,Object>> reviews=data(wms.reviewSummaries(company,ids,SecurityConstants.INNER));require(reviews.stream().allMatch(r->number(r,"pending_count")==0),"存在待人工核对的换出回传");for(Map<String,Object> s:ships)require(data(wms.receipts(company,text(s,"shipment_sn"),true,SecurityConstants.INNER)).isEmpty(),"仓库存在待记账换出回传，请先核对");}
    }
    private void refundAndPlatform(String company,Map<String,Object> e){
        Map<String,Object> raw=repository.raw(company,number(e,"original_platform_order_id"));
        require(!text(raw,"update_categories").contains("REFUND")||number(raw,"change_pending")==0,"原订单有退款变更待处理");
        try{JsonNode trade=JSON.readTree(text(raw,"raw_payload")).path("trade_fullinfo_get_response").path("trade");require(trade.isObject(),"原平台订单快照无法核对退款状态");for(JsonNode node:Arrays.asList(trade)){String status=node.path("refund_status").asText("");require(status.isEmpty()||Arrays.asList("NO_REFUND","CLOSED").contains(status),"原交易存在退款处理中或已退款，不能直接继续换出");}
            JsonNode orders=trade.path("orders").path("order");require(orders.isArray(),"原平台子单快照无法核对");boolean found=false;for(JsonNode line:orders)if(text(e,"platform_oid").equals(line.path("oid").asText())){found=true;String status=line.path("refund_status").asText("");require(status.isEmpty()||Arrays.asList("NO_REFUND","CLOSED").contains(status),"原平台子单存在退款处理中或已退款，不能直接继续换出");require(!"TRADE_CLOSED".equals(line.path("status").asText()),"原平台子单已关闭，请先核对后续售后");}require(found,"原平台子单不存在，请核对来源");
        }catch(java.io.IOException failure){throw new IllegalArgumentException("原平台订单无法读取，请先核对");}
        if("PLATFORM".equals(text(e,"source_kind"))){Map<String,Object> response=exchanges.call(company,number(e,"channel_id"),"DETAIL",map("dispute_id",e.get("dispute_id"),"fields",ExchangeService.FIELDS));Map<String,Object> p=object(response.get("exchange"));require(text(e,"dispute_id").equals(text(p,"dispute_id"))&&"12".equals(text(p,"status"))&&number(p,"num")==number(e,"requested_quantity")&&text(e,"target_description").equals(text(p,"exchange_sku")),"平台申请当前未允许原方案继续换出，请先核对；本次不会提交平台写操作");}
    }
    private void noOpenControls(String company,long id){require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_control WHERE company_code=? AND exchange_id=? AND state<>'COMPLETED'",Long.class,company,id)==0,"截单或取消仍未全部确认，请先核对原处理结果");}
    private Map<String,Object> validateStopped(String company,Map<String,Object> e){
        long id=number(e,"id");stopped(e);noOpenControls(company,id);require(active(company,id)==0,"仍有有效换出需求，请先截停；普通挂起或撤回请恢复履约");
        receipts(company,id);Map<String,Object> returned=returned(company,e);refundAndPlatform(company,e);
        if(e.get("stock_request")!=null){List<Map<String,Object>> demands=data(stock.demands(company,number(e,"channel_id"),ExchangeRounds.reference(e),SecurityConstants.INNER));require(demands.size()==1,"原换出库存需求无法核对");Map<String,Object> d=demands.get(0);require(text(d,"sku_sn").equals(text(e,"target_sku"))&&text(d,"platform_oid").equals(text(e,"platform_oid"))&&number(d,"demand_quantity")==number(d,"cancelled_quantity")+number(d,"outbound_quantity")&&number(d,"reserved_quantity")==number(d,"outbound_quantity"),"原换出需求尚未终止或仍有库存占用，请先核对");}
        long qty=number(e,"requested_quantity")-shipped(company,id);require(qty>0,"本次批准数量已全部实际换出，后续换货应关联实际发货明细另行申请");return map("quantity",qty,"shipped_quantity",shipped(company,id),"active_quantity",0,"returned",returnSnapshot(returned));
    }
    public Map<String,Object> preview(String company,long id){Map<String,Object> e=base(company,id);idle(e);Map<String,Object> result=validateStopped(company,e);result.putAll(map("control_version",e.get("control_version"),"target_sku",e.get("target_sku"),"recipient",ExchangeRounds.recipient(e),"requires_manual_refund_confirmation",true));return result;}
    private <T> T leased(String company,long id,Map<String,Object> input,Function<Map<String,Object>,T> operation){String lease=token();Map<String,Object> e=tx().execute(s->{Map<String,Object> row=exchanges.row(company,id,true);idle(row);require(number(row,"control_version")==number(input,"control_version"),"换货单已变化，请重新预览");repository.db().update("UPDATE oms_exchange SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND id=?",lease,company,id);row.put("continuation_lease",lease);return row;});try{return operation.apply(e);}finally{repository.db().update("UPDATE oms_exchange SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",company,id,lease);}}
    private Map<String,Object> lockLease(String company,long id,Map<String,Object> before){Map<String,Object> e=exchanges.row(company,id,true);require(text(before,"continuation_lease").equals(text(e,"lease_token"))&&number(e,"control_version")==number(before,"control_version")&&time(text(e,"lease_until")).isAfter(LocalDateTime.now()),"申请执行状态已变化，请核对原结果");return e;}
    private Map<String,Object> recipient(Map<String,Object> input){require(Boolean.TRUE.equals(input.get("recipient_confirmed"))&&input.get("replacement_recipient") instanceof Map,"请确认本轮换出收货信息");Map<String,Object> source=object(input.get("replacement_recipient")),result=new LinkedHashMap<>();for(String field:Arrays.asList("name","mobile","province","city","area","town","detailAddress","oaid")){String value=text(source,field).trim();require(value.length()<=500,"收货信息字段过长");result.put(field,value);}require(!OrderCarrierPolicy.province(text(result,"province")).isEmpty()&&!text(result,"city").isEmpty(),"收货省市不完整");require(!text(result,"oaid").isEmpty()||!text(result,"name").isEmpty()&&!text(result,"mobile").isEmpty()&&!text(result,"detailAddress").isEmpty(),"收货信息不完整且无OAID");return result;}
    public Map<String,Object> submit(String company,long id,Map<String,Object> input,String actor){
        require(Boolean.TRUE.equals(input.get("buyer_confirmed"))&&Boolean.TRUE.equals(input.get("refund_confirmed")),"请确认买家同意继续换货，且未退款、没有其他冲突售后处理");String reason=text(input,"reason").trim(),evidence=text(input,"evidence").trim();require(!reason.isEmpty()&&reason.length()<=500&&!evidence.isEmpty()&&evidence.length()<=500,"请填写协商依据和核对凭证");Map<String,Object> recipient=recipient(input);
        return leased(company,id,input,before->{Map<String,Object> e=base(company,id);Map<String,Object> basis=validateStopped(company,e);require(number(input,"quantity")==number(basis,"quantity"),"继续换出数量必须为当前尚未实际发出的全部剩余数量，请重新预览");
            tx().execute(s->{Map<String,Object> locked=lockLease(company,id,before);require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_round WHERE company_code=? AND exchange_id=? AND state='REVIEW'",Long.class,company,id)==0,"已有继续换出申请待审核");archive(company,locked);long round=repository.db().queryForObject("SELECT COALESCE(MAX(round_no),1)+1 FROM oms_exchange_round WHERE company_code=? AND exchange_id=?",Long.class,company,id);require(round<=100,"换出批次过多，请先核对");basis.put("previous_control_state",locked.get("control_state"));basis.put("buyer_confirmed",true);basis.put("refund_confirmed",true);basis.put("requested_quantity",locked.get("requested_quantity"));basis.put("approved_hash",hash(canonical(object(locked.get("approved_snapshot")))));basis.put("platform_oid",locked.get("platform_oid"));
                repository.insert("INSERT INTO oms_exchange_round(company_code,exchange_id,round_no,stock_reference,quantity,target_sku,state,recipient_json,basis_json,reason,evidence,actor) VALUES (?,?,?,?,?,?,'REVIEW',?,?,?,?,?)",company,id,round,"EXCHANGE:"+id+":"+round,basis.get("quantity"),locked.get("target_sku"),encode(recipient),encode(basis),reason,evidence,actor);
                repository.db().update("UPDATE oms_exchange SET fulfillment_hold=1,control_state='CONTINUE_REVIEW',next_attempt=NULL,control_version=control_version+1 WHERE company_code=? AND id=?",company,id);exchanges.event(company,id,"CONTINUE_REQUEST",text(locked,"state"),number(locked,"control_version")+1,"继续换出申请已登记，待审核；复用退回验收，未重新预占或下发仓库",map("round_no",round,"quantity",basis.get("quantity"),"target_sku",locked.get("target_sku"),"reason",reason,"evidence",evidence),actor);return null;});return exchanges.detail(company,id);});
    }
    private void archive(String company,Map<String,Object> e){long id=number(e,"id"),round=ExchangeRounds.numberOf(e);Map<String,Object> snapshot=new LinkedHashMap<>();for(String key:Arrays.asList("state","control_state","approved_snapshot","stock_request","stock_receipt","allocation_receipts","allocation_policy","fulfillment_line_id","review_by","reviewed_at"))snapshot.put(key,e.get(key));
        repository.db().update("INSERT INTO oms_exchange_round(company_code,exchange_id,round_no,stock_reference,quantity,target_sku,state,recipient_json,basis_json,snapshot_json,reason,evidence,actor,fulfillment_line_id) VALUES (?,?,?,?,?,?,'TERMINATED',?,?,?,'原换出履约结束归档','原截单及库存回执','系统',?) ON DUPLICATE KEY UPDATE snapshot_json=VALUES(snapshot_json),state='TERMINATED'",company,id,round,ExchangeRounds.reference(e),ExchangeRounds.quantityOf(e),e.get("target_sku"),encode(ExchangeRounds.recipient(e)),encode(map("requested_quantity",e.get("requested_quantity"))),encode(snapshot),e.get("fulfillment_line_id"));
    }
    public Map<String,Object> review(String company,long id,long round,Map<String,Object> input,String actor){String decision=text(input,"decision"),reason=text(input,"reason").trim();require(Arrays.asList("APPROVE","REJECT").contains(decision)&&!reason.isEmpty()&&reason.length()<=500,"请选择审核结论并填写依据");return leased(company,id,input,before->{
        Map<String,Object> pending=repository.db().query("SELECT * FROM oms_exchange_round WHERE company_code=? AND exchange_id=? AND round_no=?",ROW,company,id,round).stream().findFirst().orElseThrow(()->new IllegalArgumentException("继续换出申请不存在或无权访问"));require("REVIEW".equals(text(pending,"state")),"该批次已审核，请刷新");Map<String,Object> e="APPROVE".equals(decision)?base(company,id):exchanges.row(company,id,false),basis=object(pending.get("basis_json"));
        if("APPROVE".equals(decision)){require(Boolean.TRUE.equals(input.get("refund_confirmed")),"审核时请重新核对未退款且无冲突售后");Map<String,Object> now=validateStopped(company,e);require(number(now,"quantity")==number(pending,"quantity")&&text(e,"target_sku").equals(text(pending,"target_sku"))&&number(e,"requested_quantity")==number(basis,"requested_quantity")&&hash(canonical(object(e.get("approved_snapshot")))).equals(text(basis,"approved_hash")),"原审核方案或可换出数量已变化，请拒绝后重新申请");}
        tx().execute(s->{Map<String,Object> locked=lockLease(company,id,before);require("CONTINUE_REVIEW".equals(text(locked,"control_state")),"换货控制状态已变化");require(repository.db().update("UPDATE oms_exchange_round SET state=?,reviewed_by=?,review_reason=?,reviewed_at=NOW() WHERE company_code=? AND exchange_id=? AND round_no=? AND state='REVIEW'","APPROVE".equals(decision)?"APPROVED":"REJECTED",actor,reason,company,id,round)==1,"批次审核结果已变化");
            if("APPROVE".equals(decision))repository.db().update("UPDATE oms_exchange SET fulfillment_round=?,round_quantity=?,round_recipient=?,fulfillment_line_id=NULL,fulfillment_order_id=NULL,stock_request=NULL,stock_receipt=NULL,allocation_status='NONE',allocation_quantity=0,allocation_receipts=NULL,allocation_policy=NULL,fulfillment_hold=0,control_state='NONE',state='APPROVED',stage='REPLACEMENT',problem_codes='',problem_message='',last_error='',review_by=?,reviewed_at=NOW(),next_attempt=NOW(),control_version=control_version+1 WHERE company_code=? AND id=?",round,pending.get("quantity"),pending.get("recipient_json"),actor,company,id);
            else repository.db().update("UPDATE oms_exchange SET control_state=?,control_version=control_version+1 WHERE company_code=? AND id=?",basis.get("previous_control_state"),company,id);
            exchanges.event(company,id,"CONTINUE_REVIEW",text(locked,"state"),number(locked,"control_version")+1,"APPROVE".equals(decision)?"继续换出审核通过，等待本轮重新预占；原退回和已截停单据保留":"继续换出申请已拒绝，原结束结果保留",map("round_no",round,"decision",decision,"reason",reason),actor);return null;});return exchanges.detail(company,id);});}
    /** Recheck old receipt queues and source refund state before a new round can reserve or dispatch. */
    public void guardExecution(String company,long id){Map<String,Object> e=base(company,id);if(ExchangeRounds.numberOf(e)==1)return;ExchangeFulfillment.planUnchanged(e);List<Map<String,Object>> rounds=repository.db().query("SELECT * FROM oms_exchange_round WHERE company_code=? AND exchange_id=? AND round_no=?",ROW,company,id,ExchangeRounds.numberOf(e));require(rounds.size()==1,"本轮审核记录不存在");Map<String,Object> round=rounds.get(0);require(Arrays.asList("APPROVED","WAIT_STOCK","PROCESSING").contains(text(round,"state"))&&number(round,"quantity")==ExchangeRounds.quantityOf(e)&&text(round,"target_sku").equals(text(e,"target_sku"))&&canonical(object(round.get("recipient_json"))).equals(canonical(ExchangeRounds.recipient(e))),"本轮换出方案与审核记录不一致");long earlier=repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id WHERE s.company_code=? AND s.exchange_id=? AND s.business_type='EXCHANGE' AND s.fulfillment_round<>?",Long.class,company,id,ExchangeRounds.numberOf(e));require(earlier+ExchangeRounds.quantityOf(e)<=number(e,"requested_quantity"),"原轮次新增实际出库，本轮数量已失效，请挂起核对");returned(company,e);receipts(company,id);refundAndPlatform(company,e);require(shipped(company,id)+active(company,id)<=number(e,"requested_quantity"),"累计实发与有效待发超过本次批准数量，禁止继续执行");}
}
